use crate::money::{money, Currency};
use crate::position::AccountBalance;

pub fn from_json(v: &serde_json::Value) -> Vec<AccountBalance> {
    let mut out: Vec<AccountBalance> = v
        .as_array()
        .map(Vec::as_slice)
        .unwrap_or_default()
        .iter()
        .filter_map(|b| {
            Some(AccountBalance {
                account: b.get("account")?.as_str()?.to_string(),
                as_of: b.get("asOf")?.as_str()?.to_string(),
                balance: money(
                    b.get("signedMinor")?.as_i64()?,
                    Currency::new(b.get("currency").and_then(|c| c.as_str()).unwrap_or("USD")).unwrap_or(Currency::USD),
                ),
            })
        })
        .collect();
    out.sort_by(|a, b| a.account.cmp(&b.account).then(a.as_of.cmp(&b.as_of)));
    out
}
